-- Traitements possibles contre les ravageurs et maladies de chaque fiche (préventif d'abord, produits utilisables au jardin bio)
alter table public.species add column pests_treatment text;
update public.species set pests_treatment='Rouille : retirer les feuilles atteintes, purin de prêle en préventif ; ne pas replanter d''ail ou d''oignon au même endroit avant 4 ans. Pourriture blanche : aucun traitement, arracher et jeter les plants touchés, sol bien drainé.' where slug='ail';
update public.species set pests_treatment='Pucerons : jet d''eau, savon noir dilué (1 cuillère à soupe par litre) ; laisser agir les coccinelles.' where slug='aneth';
update public.species set pests_treatment='Pucerons noirs : jet d''eau puis savon noir dilué, coccinelles bienvenues. Limaces : ramassage le soir, granulés au phosphate ferrique (autorisés en bio). Pourriture : planter en sol bien drainé, ne pas arroser en excès.' where slug='artichaut';
update public.species set pests_treatment='Criocère : ramasser les adultes et larves à la main, couper et brûler les tiges sèches à l''automne. Rouille : retirer les tiges touchées. Mouche : butter pour protéger les turions.' where slug='asperge';
update public.species set pests_treatment='Doryphores : ramassage à la main, adultes et larves, matin et soir. Pucerons : savon noir dilué. Acariens : brumiser le feuillage, savon noir. Altises : arrosages réguliers, paillage, voile anti-insectes.' where slug='aubergine';
update public.species set pests_treatment='Limaces : ramassage le soir, phosphate ferrique. Pucerons : savon noir dilué. Mildiou : arroser au pied le matin, espacer les plants, retirer les feuilles atteintes.' where slug='basilic';
update public.species set pests_treatment='Pucerons noirs : savon noir dilué, purin d''ortie. Cercosporiose : retirer les feuilles tachées, rotation de 3 ans, purin de prêle en préventif.' where slug='betterave';
update public.species set pests_treatment='Pucerons : jet d''eau, savon noir dilué. Mineuse : retirer et jeter les feuilles minées, voile anti-insectes. Limaces : ramassage, phosphate ferrique.' where slug='blette';
update public.species set pests_treatment='Piéride : filet anti-insectes posé dès la plantation, ramassage des œufs jaunes, Bacillus thuringiensis sur les chenilles. Altises : paillage, arrosages réguliers, voile. Hernie : rotation de 4 ans, chaux si le sol est acide.' where slug='brocoli';
update public.species set pests_treatment='Pucerons : laissez-les, ils protègent les légumes voisins ; sinon jet d''eau. Piéride : ramassage des chenilles à la main.' where slug='capucine';
update public.species set pests_treatment='Mouche de la carotte : voile anti-insectes à mailles fines posé dès le semis, semis clairs, association avec le poireau, éclaircir le soir. Nématodes : rotation de 3 ans, œillet d''Inde alentour.' where slug='carotte';
update public.species set pests_treatment='Mouche du céleri : voile anti-insectes, retirer les feuilles minées. Rouille et septoriose : retirer les feuilles atteintes, aérer, purin de prêle ; bouillie bordelaise en dernier recours.' where slug='celeri-rave';
update public.species set pests_treatment='Chenilles (piéride, noctuelle) : filet anti-insectes dès la plantation, ramassage, Bacillus thuringiensis. Altises : arrosages réguliers, paillage, voile. Hernie : rotation de 4 ans, chaulage du sol acide, plants sains.' where slug='chou';
update public.species set pests_treatment='Piéride : filet anti-insectes, ramassage des œufs et chenilles, Bacillus thuringiensis. Pucerons cendrés : jet d''eau puis savon noir dilué, retirer les feuilles très atteintes.' where slug='kale';
update public.species set pests_treatment='Piéride : filet anti-insectes, Bacillus thuringiensis. Altises : paillage, arrosages réguliers. Mouche du chou : voile posé dès la plantation, collerettes autour du pied. Rotation de 4 ans.' where slug='chou-fleur';
update public.species set pests_treatment='Altises : voile anti-insectes, arrosages réguliers, paillage. Piéride : filet, ramassage des chenilles, Bacillus thuringiensis.' where slug='chou-rave';
update public.species set pests_treatment='Rouille : couper les tiges atteintes au ras du sol (elles repoussent), purin de prêle. Mouche de l''oignon : voile fin, ne pas replanter au même endroit.' where slug='ciboulette';
update public.species set pests_treatment='Oïdium : soufre mouillable, ou lait dilué (1 part pour 9 d''eau) en préventif ; retirer les feuilles atteintes. Pucerons : savon noir dilué. Acariens : brumiser le dessous des feuilles par temps chaud.' where slug='concombre';
update public.species set pests_treatment='Pucerons : jet d''eau, savon noir dilué. Montée à graines : semer en place à l''ombre légère, en plusieurs fois, et arroser régulièrement.' where slug='coriandre';
update public.species set pests_treatment='Oïdium : soufre mouillable ou lait dilué, retirer les feuilles atteintes. Pucerons : savon noir. Limaces : ramassage, phosphate ferrique sur les jeunes plants ; poser les fruits sur une planche.' where slug='courge';
update public.species set pests_treatment='Oïdium : soufre mouillable, ou lait dilué (1 part pour 9 d''eau) dès les premiers signes ; retirer les feuilles atteintes. Pucerons : savon noir dilué. Limaces : ramassage le soir, phosphate ferrique.' where slug='courgette';
update public.species set pests_treatment='Mouche de l''oignon : voile fin posé dès la plantation, rotation de 4 ans. Rouille : retirer les feuilles atteintes, purin de prêle, espacer les plants.' where slug='echalote';
update public.species set pests_treatment='Mildiou : variétés résistantes, espacer les semis, arroser au pied, retirer les feuilles atteintes. Limaces : ramassage, phosphate ferrique. Pucerons : savon noir dilué.' where slug='epinard';
update public.species set pests_treatment='Pucerons : jet d''eau puis savon noir dilué. Limaces : ramassage le soir, phosphate ferrique sur les jeunes plants.' where slug='fenouil';
update public.species set pests_treatment='Pucerons noirs : pincer l''extrémité des tiges à la floraison (les pucerons s''y concentrent), savon noir dilué. Bruches : semences saines, graines récoltées placées 48 h au congélateur avant stockage.' where slug='feve';
update public.species set pests_treatment='Limaces : ramassage, phosphate ferrique, pailler à la paille. Botrytis : aérer, retirer les fruits pourris, éviter de mouiller les fruits. Oiseaux : filet.' where slug='fraise';
update public.species set pests_treatment='Ver du framboisier : récolter souvent et retirer les fruits véreux, griffer le sol au pied en hiver. Botrytis : aérer en taillant les vieilles cannes, retirer les fruits atteints. Drageons : arracher ceux qui s''éloignent.' where slug='framboisier';
update public.species set pests_treatment='Pucerons : savon noir dilué, taille aérée. Tenthrède : ramasser les larves sur le dessous des feuilles. Oïdium : soufre mouillable, tailler pour aérer.' where slug='groseillier';
update public.species set pests_treatment='Pucerons noirs : savon noir dilué, pincer l''extrémité des tiges attaquées. Limaces : ramassage, phosphate ferrique sur les jeunes plants. Rouille : retirer les feuilles atteintes, rotation de 3 ans.' where slug='haricot-a-rames';
update public.species set pests_treatment='Pucerons noirs : savon noir dilué. Limaces : ramassage, phosphate ferrique sur les jeunes plants. Rouille : retirer les feuilles atteintes, rotation de 3 ans, ne pas travailler les plants mouillés.' where slug='haricot-nain';
update public.species set pests_treatment='Limaces : ramassage le soir, phosphate ferrique. Oïdium : espacer les semis, retirer les rosettes atteintes, éviter l''excès d''humidité.' where slug='mache';
update public.species set pests_treatment='Pyrale : lâchers de trichogrammes (insectes auxiliaires), broyer les tiges après récolte. Corbeaux : semer plus profond, pailler, effaroucheur. Limaces : ramassage, phosphate ferrique.' where slug='mais';
update public.species set pests_treatment='Oïdium : soufre mouillable, ou lait dilué en préventif. Pucerons : savon noir dilué. Limaces : ramassage, phosphate ferrique ; poser les fruits sur une tuile ou une planche.' where slug='melon';
update public.species set pests_treatment='Rouille : couper et jeter les tiges atteintes, ne pas replanter au même endroit, purin de prêle. Altises : arrosages réguliers, voile.' where slug='menthe';
update public.species set pests_treatment='Oiseaux : filet à mailles fines avant la coloration des fruits. Pourriture grise : aérer, retirer les baies atteintes, éviter d''arroser en pluie.' where slug='myrtille';
update public.species set pests_treatment='Altises et mouche du chou : voile anti-insectes dès le semis, arrosages réguliers, paillage. Hernie : rotation de 4 ans, chaulage du sol acide.' where slug='navet';
update public.species set pests_treatment='Limaces sur les jeunes plants : ramassage le soir, phosphate ferrique.' where slug='oeillet-d-inde';
update public.species set pests_treatment='Mouche de l''oignon : voile fin posé dès la plantation, alterner les rangs avec de la carotte. Mildiou : espacer, arroser au pied, bouillie bordelaise en préventif si l''année est humide. Pourriture du collet : bien sécher avant de stocker.' where slug='oignon';
update public.species set pests_treatment='Pucerons : jet d''eau, savon noir dilué. Rouille : couper les feuilles atteintes, elles repoussent. Limaces : ramassage, phosphate ferrique.' where slug='oseille';
update public.species set pests_treatment='Altises : voile anti-insectes dès le semis, arrosages réguliers. Limaces : ramassage, phosphate ferrique.' where slug='pak-choi';
update public.species set pests_treatment='Mouche de la carotte : voile à mailles fines. Chancre : sol léger et bien drainé, rotation de 3 à 4 ans, variétés résistantes.' where slug='panais';
update public.species set pests_treatment='Oïdium : soufre mouillable ou lait dilué en préventif. Pucerons : savon noir dilué. Limaces : ramassage, phosphate ferrique ; fruits posés sur une tuile.' where slug='pasteque';
update public.species set pests_treatment='Mouche de la carotte : voile à mailles fines, ne pas semer après des carottes. Limaces : ramassage, phosphate ferrique.' where slug='persil';
update public.species set pests_treatment='Pucerons verts : savon noir dilué. Tordeuse : semer tôt ou tard pour éviter la période de vol. Oiseaux : filet ou fils tendus sur les semis.' where slug='petit-pois';
update public.species set pests_treatment='Pucerons : savon noir dilué. Aleurodes : pièges jaunes englués, savon noir. Acariens : brumiser le dessous des feuilles, bassiner par temps sec.' where slug='piment';
update public.species set pests_treatment='Teigne : voile anti-insectes en mai-juin et en septembre, Bacillus thuringiensis. Rouille : retirer les feuilles atteintes, purin de prêle, rotation de 4 ans. Mouche mineuse : voile fin.' where slug='poireau';
update public.species set pests_treatment='Pucerons : savon noir dilué. Acariens : brumiser, savon noir. Pourriture apicale : pas de traitement, arroser régulièrement et pailler pour garder le sol frais.' where slug='poivron';
update public.species set pests_treatment='Mildiou : bouillie bordelaise en préventif dès les premières pluies, butter, retirer les fanes atteintes. Doryphores : ramasser adultes et larves. Taupins : pièges (tranches de pomme de terre enterrées), nématodes auxiliaires.' where slug='pomme-de-terre';
update public.species set pests_treatment='Altises : voile anti-insectes dès le semis, arrosages réguliers, paillage fin.' where slug='radis';
update public.species set pests_treatment='Limaces : ramassage, phosphate ferrique sur les jeunes pousses. Pourriture : drainer le sol, ne pas laisser d''eau stagner sur la couronne.' where slug='rhubarbe';
update public.species set pests_treatment='Pourriture des racines : sol drainant (ajouter du sable), arrosages rares. Cochenilles : brosser avec de l''eau savonneuse (savon noir).' where slug='romarin';
update public.species set pests_treatment='Altises : voile anti-insectes dès le semis, arrosages réguliers.' where slug='roquette';
update public.species set pests_treatment='Limaces : ramassage le soir, phosphate ferrique, pièges à bière. Pucerons : savon noir dilué. Mildiou : espacer, arroser le matin au pied, retirer les feuilles atteintes.' where slug='salade';
update public.species set pests_treatment='Oïdium : soufre mouillable, tailler pour aérer, éviter d''arroser le feuillage.' where slug='sauge';
update public.species set pests_treatment='Pucerons : jet d''eau, savon noir dilué. Oïdium : lait dilué (1 part pour 9 d''eau) ou soufre, retirer les feuilles atteintes.' where slug='souci';
update public.species set pests_treatment='Pourriture : sol très drainant (sable, cailloux), arrosages rares.' where slug='thym';
update public.species set pests_treatment='Mildiou : bouillie bordelaise en préventif dès les premières pluies, retirer les feuilles basses, tuteurer et aérer, arroser au pied ; arracher et jeter les plants très touchés. Pucerons : savon noir dilué. Aleurodes : pièges jaunes englués, savon noir. Noctuelles : ramassage des chenilles, Bacillus thuringiensis.' where slug='tomate';
update public.species set pests_treatment='Mildiou : bouillie bordelaise en préventif, retirer les feuilles basses, arroser au pied. Pucerons : savon noir dilué. Aleurodes : pièges jaunes englués, savon noir.' where slug='tomate-cerise';
update public.species set pests_treatment='Limaces sur les jeunes pousses : ramassage le soir, phosphate ferrique.' where slug='topinambour';
update public.species set pests_treatment='Limaces sur les jeunes plants : ramassage, phosphate ferrique. Oiseaux : voile ou sacs en papier sur les capitules à maturité.' where slug='tournesol';
